  display: block;
  float: left !important;
  cursor: pointer;
  position: relative;
  width: 36px;
  flex: 0 0 36px;
  height: 18px;
  padding: 0;
  margin: 0;
  overflow: hidden;
  -moz-border-radius: 50rem;
  -webkit-border-radius: 50rem;
  border-radius: 50rem;
}
.store-addons-for-woocommerce-switcher label span {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  background-color: #fff;
  -moz-border-radius: 50%;
  -webkit-border-radius: 50%;
  border-radius: 50%;
  -moz-transition: left 0.15s ease-out;
  -o-transition: left 0.15s ease-out;
  -webkit-transition: left 0.15s ease-out;
  transition: left 0.15s ease-out;
}
.store-addons-for-woocommerce-switcher label input {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
}
.store-addons-for-woocommerce-switcher label input:checked ~ em {
  background-color: var(--store-addons-for-woocommerce-color);
}
.store-addons-for-woocommerce-switcher label input:checked ~ em::before {
  opacity: 0;
}
.store-addons-for-woocommerce-switcher label input:checked ~ em::after {
  opacity: 1;
}
.store-addons-for-woocommerce-switcher label input:checked ~ span {
  left: 20px;
}
